    <!-- Header -->
    <header class="bg-white border-b border-gray-200 sticky top-0 z-10 shadow-sm">
        <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div class="flex items-center justify-between h-16">
                <div class="flex items-center gap-3">
                    <div class="bg-brand-600 text-white rounded-lg w-9 h-9 flex items-center justify-center font-bold text-lg">P</div>
                    <div>
                        <h1 class="text-lg font-bold text-gray-900 leading-tight">Prispulsen</h1>
                        <p class="text-xs text-gray-500 leading-tight">Karlskrona · matpriser</p>
                    </div>
                </div>
                <div id="last-updated" class="flex items-center gap-2 text-sm text-gray-500">
                    <span class="inline-block w-2 h-2 rounded-full bg-gray-300 animate-pulse"></span>
