def category_offers(category: str, request: Request):
    """
    Return all current offers for a category, sorted by unit_price asc.

    Returns 404 if the category doesn't exist or has no current offers.
    """
    request_id = request.headers.get("X-Request-ID", "-")
    try:
        offers = db.get_offers_by_category(category)
    except psycopg2.Error as exc:
        logger.error(
            "DB error in /categories/%s (request_id=%s): %s",
