def _row_to_dict(row: Any) -> dict:
    """Convert a RealDictRow to a plain dict with ISO timestamps and remapped store names."""
    result = {}
    for k, v in dict(row).items():
        if hasattr(v, "isoformat"):
            result[k] = v.isoformat()
        else:
            result[k] = v
    # Remap store names to friendlier display names
    if "store_name" in result and result["store_name"] in STORE_NAME_MAP:
        result["store_name"] = STORE_NAME_MAP[result["store_name"]]
    return result

